#include <iostream>
#include <cmath>
#include <vector>
#include <string>
#include <algorithm>

using namespace std;

int weight;
int itemMass;
vector<bool> arr(100, false);

class Main {
public:
    bool isBalanced() {
        bool isBalance = false;
        long long pod1 = itemMass, pod2 = 0;
        while (true) {
            if (pod1 > pod2) {
                long long nextMass = getMass(pod1 - pod2);
                if (nextMass != 0) {
                    pod2 += nextMass;
                } else {
                    break;
                }
            } else if (pod1 < pod2) {
                long long nextMass = getMass(pod2 - pod1);
                if (nextMass != 0) {
                    pod1 += nextMass;
                } else {
                    break;
                }
            } else {
                isBalance = true;
                break;
            }
        }
        return isBalance;
    }

    long long getMass(long long mass) {
        long long result;
        int logBase = (int)(log(mass) / log(weight));
        // To avoid floating point inaccuracies, handle logBase < 0
        if (logBase < 0) logBase = 0;
        // Compute bi = (weight^(logBase+1) - 1) / (weight - 1)
        // Use pow carefully
        long long pow_weight_logBasePlus1 = (long long)pow(weight, logBase + 1);
        long long sumTotal = (pow_weight_logBasePlus1 - 1) / (weight - 1);
        if (mass > sumTotal && !arr[logBase + 1]) {
            result = pow_weight_logBasePlus1;
            arr[logBase + 1] = true;
        } else if (mass <= sumTotal && !arr[logBase]) {
            result = (long long)pow(weight, logBase);
            arr[logBase] = true;
        } else {
            result = 0;
        }
        return result;
    }
};

int main() {
    cin >> weight >> itemMass;
    Main instance;
    if (instance.isBalanced())
        cout << "YES" << endl;
    else
        cout << "NO" << endl;
    return 0;
}

